.expansion-sim-container {
    padding: 28px 32px;
    background: #f0f2f5;
    min-height: 100vh;
    font-family: -apple-system, 'Segoe UI', 'Inter', Helvetica, Arial, sans-serif;
    color: #1e293b;
}
.expansion-sim-header {
    background: linear-gradient(135deg, #1a2744 0%, #243b63 60%, #1e5a3a 100%);
    border-radius: 6px;
    padding: 0;
    margin-bottom: 24px;
    overflow: hidden;
    position: relative;
}
.expansion-sim-header::before {
    content: '';
    position: absolute;
    top: 0; right: 0;
    width: 260px; height: 100%;
    background: url("data:image/svg+xml,%3Csvg width='260' height='120' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M0 120 Q60 80 130 90 T260 40 L260 0 L0 0Z' fill='rgba(255,255,255,0.04)'/%3E%3C/svg%3E") no-repeat right top;
    background-size: cover;
    pointer-events: none;
}
.expansion-sim-header-inner {
    padding: 32px 36px 28px;
    position: relative;
}
.expansion-sim-logo {
    display: inline-block;
    background: rgba(255,255,255,0.12);
    border: 1px solid rgba(255,255,255,0.18);
    border-radius: 4px;
    padding: 4px 14px;
    font-size: 0.7rem;
    font-weight: 700;
    letter-spacing: 0.18em;
    color: #a8c4e0;
    text-transform: uppercase;
    margin-bottom: 14px;
}
.expansion-sim-header h1 {
    color: #ffffff;
    font-size: 1.85rem;
    font-weight: 700;
    margin: 0 0 6px 0;
    letter-spacing: -0.01em;
}
.expansion-sim-subtitle {
    color: #94b8d8;
    font-size: 0.95rem;
    margin: 0;
    font-weight: 400;
}
.expansion-sim-period-bar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    background: #ffffff;
    border: 1px solid #e2e8f0;
    border-radius: 4px;
    padding: 12px 20px;
    margin-bottom: 20px;
    font-size: 0.85rem;
}
.expansion-sim-period-left {
    color: #64748b;
    font-weight: 500;
}
.expansion-sim-period-left span:nth-child(2) {
    font-size: 1.1rem;
    font-weight: 700;
    color: #1a2744;
    margin: 0 2px;
}
.expansion-sim-round-title {
    font-weight: 600;
    color: #1a2744;
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.04em;
}
.expansion-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 16px;
    margin-bottom: 24px;
}
.expansion-sim-kpi-card {
    background: #ffffff;
    border: 1px solid #e2e8f0;
    border-radius: 4px;
    padding: 20px 18px;
    position: relative;
}
.expansion-sim-kpi-card::after {
    content: '';
    position: absolute;
    bottom: 0; left: 0; right: 0;
    height: 3px;
    border-radius: 0 0 4px 4px;
}
.expansion-sim-kpi-capital::after { background: #1a2744; }
.expansion-sim-kpi-invested::after { background: #dc2626; }
.expansion-sim-kpi-revenue::after { background: #059669; }
.expansion-sim-kpi-score::after { background: #2563eb; }
.expansion-sim-kpi-label {
    font-size: 0.7rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: #64748b;
    margin-bottom: 8px;
}
.expansion-sim-kpi-value {
    font-size: 1.7rem;
    font-weight: 700;
    color: #1e293b;
}
.expansion-sim-kpi-capital .expansion-sim-kpi-value { color: #1a2744; }
.expansion-sim-kpi-invested .expansion-sim-kpi-value { color: #dc2626; }
.expansion-sim-kpi-revenue .expansion-sim-kpi-value { color: #059669; }
.expansion-sim-kpi-score .expansion-sim-kpi-value { color: #2563eb; }
.expansion-sim-briefing {
    background: #ffffff;
    border: 1px solid #e2e8f0;
    border-left: 4px solid #2563eb;
    border-radius: 4px;
    padding: 22px 24px;
    margin-bottom: 24px;
    position: relative;
}
.expansion-sim-briefing-badge {
    display: inline-block;
    background: #2563eb;
    color: #ffffff;
    font-size: 0.6rem;
    font-weight: 700;
    letter-spacing: 0.14em;
    padding: 3px 10px;
    border-radius: 3px;
    margin-bottom: 14px;
}
.expansion-sim-briefing-text {
    font-size: 0.9rem;
    line-height: 1.65;
    color: #334155;
}
.expansion-sim-controls {
    background: #ffffff;
    border: 1px solid #e2e8f0;
    border-radius: 4px;
    padding: 24px 28px;
    margin-bottom: 24px;
}
.expansion-sim-controls h3 {
    font-size: 0.8rem;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    color: #1a2744;
    font-weight: 700;
    margin: 0 0 20px 0;
    padding-bottom: 12px;
    border-bottom: 1px solid #e2e8f0;
}
.expansion-sim-field {
    margin-bottom: 18px;
}
.expansion-sim-field label {
    display: block;
    font-size: 0.8rem;
    font-weight: 600;
    color: #475569;
    margin-bottom: 6px;
}
.expansion-sim-select,
.expansion-sim-input {
    width: 100%;
    padding: 10px 14px;
    border: 1px solid #cbd5e1;
    border-radius: 4px;
    font-size: 0.88rem;
    color: #1e293b;
    background: #f8fafc;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
    font-family: inherit;
}
.expansion-sim-select:focus,
.expansion-sim-input:focus {
    outline: none;
    border-color: #2563eb;
    box-shadow: 0 0 0 3px rgba(37,99,235,0.1);
}
.expansion-sim-hint {
    display: block;
    font-size: 0.72rem;
    color: #94a3b8;
    margin-top: 4px;
}
.expansion-sim-range-row {
    display: flex;
    align-items: center;
    gap: 12px;
}
.expansion-sim-range {
    flex: 1;
    -webkit-appearance: none;
    height: 6px;
    background: #e2e8f0;
    border-radius: 3px;
    outline: none;
}
.expansion-sim-range::-webkit-slider-thumb {
    -webkit-appearance: none;
    width: 20px;
    height: 20px;
    border-radius: 50%;
    background: #2563eb;
    cursor: pointer;
    border: 2px solid #ffffff;
    box-shadow: 0 1px 4px rgba(0,0,0,0.2);
}
.expansion-sim-range-min,
.expansion-sim-range-max {
    font-size: 0.72rem;
    color: #94a3b8;
    font-weight: 500;
    min-width: 40px;
}
.expansion-sim-range-max { text-align: right; }
.expansion-sim-range-value {
    font-size: 1rem;
    font-weight: 700;
    color: #2563eb;
    min-width: 20px;
    text-align: center;
}
.expansion-sim-btn-row {
    display: flex;
    gap: 12px;
    margin-top: 24px;
    padding-top: 16px;
    border-top: 1px solid #e2e8f0;
}
.expansion-sim-btn-primary {
    background: #1a2744;
    color: #ffffff;
    border: none;
    padding: 11px 28px;
    border-radius: 4px;
    font-size: 0.88rem;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.2s ease;
}
.expansion-sim-btn-primary:hover {
    background: #243b63;
}
.expansion-sim-btn-undo {
    background: transparent;
    color: #64748b;
    border: 1px solid #cbd5e1;
    padding: 11px 20px;
    border-radius: 4px;
    font-size: 0.82rem;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.2s ease;
}
.expansion-sim-btn-undo:hover {
    background: #f8fafc;
    color: #475569;
}
.expansion-sim-history {
    background: #ffffff;
    border: 1px solid #e2e8f0;
    border-radius: 4px;
    padding: 20px 24px;
    margin-bottom: 24px;
    overflow-x: auto;
}
.expansion-sim-history table {
    margin: 0;
    font-size: 0.82rem;
}
.expansion-sim-history th {
    background: #f8fafc;
    color: #475569;
    font-weight: 600;
    text-transform: uppercase;
    font-size: 0.7rem;
    letter-spacing: 0.04em;
    border-bottom: 2px solid #e2e8f0;
    padding: 10px 12px;
}
.expansion-sim-history td {
    padding: 10px 12px;
    border-bottom: 1px solid #f1f5f9;
    color: #334155;
}
.expansion-sim-chart {
    background: #ffffff;
    border: 1px solid #e2e8f0;
    border-radius: 4px;
    padding: 24px;
    height: 340px;
}
@media (max-width: 768px) {
    .expansion-sim-container { padding: 16px; }
    .expansion-sim-kpi-grid { grid-template-columns: repeat(2, 1fr); gap: 10px; }
    .expansion-sim-header-inner { padding: 24px 20px 20px; }
    .expansion-sim-header h1 { font-size: 1.4rem; }
    .expansion-sim-controls { padding: 18px 16px; }
    .expansion-sim-btn-row { flex-direction: column; }
    .expansion-sim-period-bar { flex-direction: column; gap: 8px; text-align: center; }
}

