        getChartData(state) {
            var labels = state.domainState.investmentHistory.map(function(_, i) { return 'R' + (i + 1); });
            return {
                performanceChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.investmentHistory },
                        { data: state.domainState.revenueHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var totalInvested = history.reduce(function(s, r) { return s + (r.results ? r.results.investment : 0); }, 0);
            var finalRevenue = history.length > 0 && history[history.length - 1].results ? history[history.length - 1].results.cumulativeRevenue : 0;
            var finalScore = history.length > 0 && history[history.length - 1].results ? history[history.length - 1].results.totalScore : 0;
            var roi = totalInvested > 0 ? ((finalRevenue - totalInvested) / totalInvested * 100) : 0;

            var performance = 'Needs Improvement';
            if (finalScore >= 80 && roi > 300) performance = 'Excellent';
            else if (finalScore >= 60 && roi > 150) performance = 'Good';
            else if (finalScore >= 40) performance = 'Satisfactory';

            var insights = [];
            if (finalScore >= 80) insights.push('Strong strategic decisions across all rounds.');
            if (roi > 300) insights.push('Outstanding projected ROI on international expansion.');
            if (finalScore < 40) insights.push('Consider revisiting market selection and entry mode choices.');
            if (roi < 100) insights.push('Investment levels may be too high relative to revenue potential.');

            var overallScore = Math.max(0, Math.min(100, Math.round(finalScore - 80)));

            return {
                totalInvested: totalInvested,
                overallScore: overallScore,
                score: overallScore,
                projectedRevenueY3: finalRevenue,
                roi: Math.round(roi),
                strategicScore: finalScore,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (state.currentPeriod === 1 && results.scoreGain < 60) return window.mySimulation.t('hint_research');
            if (state.currentPeriod === 2 && state.domainState.cash < 500000) return window.mySimulation.t('hint_budget_tight');
